<section class="page-header"><div><h1>Repository Health Dashboard</h1><p>Question Quality · Review actionable quality signals across the question repository.</p></div><span class="health-score"><?= (int) $healthScore ?>%</span></section>
<div class="stats-grid"><article class="card stat-card"><span class="stat-label">Health score</span><strong class="stat-value"><?= $healthScore ?>%</strong></article><article class="card stat-card"><span class="stat-label">Errors</span><strong class="stat-value"><?= (int) ($severitySummary["error"] ?? 0) ?></strong></article><article class="card stat-card"><span class="stat-label">Warnings</span><strong class="stat-value"><?= (int) ($severitySummary["warning"] ?? 0) ?></strong></article><article class="card stat-card"><span class="stat-label">Info</span><strong class="stat-value"><?= (int) ($severitySummary["info"] ?? 0) ?></strong></article></div>
<section class="card"><h2>Priority Issue Summary</h2><div class="record-list"><?php foreach ($issueGroupLabels as $key => $label): ?><div class="metric-row"><strong><?= htmlspecialchars($label) ?></strong><span class="badge badge-warning"><?= count($issueGroups[$key] ?? []) ?></span></div><?php endforeach; ?></div></section>
<section class="card"><h2>Repository Summary</h2><div class="metric-list"><?php foreach (['Total Questions'=>'totalQuestions','Total Issues'=>'totalIssues','Errors'=>'errors','Warnings'=>'warnings','Information'=>'infos'] as $label=>$key): ?><div class="metric-row"><strong><?= $label ?></strong><span><?= (int) $report->statistics->{$key} ?></span></div><?php endforeach; ?></div></section>
<?php $distributions=['Difficulty'=>$report->statistics->questionsPerDifficulty,'Status'=>$report->statistics->questionsPerStatus,'Board'=>$report->statistics->questionsPerBoard,'Subject'=>$report->statistics->questionsPerSubject,'Domain'=>$report->statistics->questionsPerDomain,'Topic'=>$report->statistics->questionsPerTopic,'Concept'=>$report->statistics->questionsPerConcept]; ?>
<section><h2>Coverage and distributions</h2><div class="card-grid"><?php foreach ($distributions as $title=>$items): ?><article class="card"><h3><?= htmlspecialchars($title) ?></h3><?php if (empty($items)): ?><p class="muted-note">No data</p><?php else: ?><div class="metric-list"><?php foreach ($items as $name=>$count): ?><div class="metric-row"><span><?= htmlspecialchars((string) $name) ?></span><strong><?= (int) $count ?></strong></div><?php endforeach; ?></div><?php endif; ?></article><?php endforeach; ?></div></section>
<section class="card"><h2>Repository Issues</h2><?php if (empty($report->issues)): ?><div class="empty-state">No issues found.</div><?php else: ?><div class="record-list"><?php foreach ($report->issues as $issue): ?><article class="record-card"><div><strong>#<?= htmlspecialchars((string) $issue->entityId) ?></strong><p><?= htmlspecialchars($issue->message) ?></p></div><div class="record-meta"><span class="badge badge-danger"><?= htmlspecialchars($issue->severity) ?></span><code><?= htmlspecialchars($issue->code) ?></code></div></article><?php endforeach; ?></div><?php endif; ?></section>
